    "Breaking the Seal": {tip:"Clear the fort debris at the Kharid-et exterior excavation. Requires completion of the Archaeology tutorial.",loc:"Kharid-et Dig Site",req:"12 Archaeology (boostable), Archaeology tutorial completed",items:["Centurion's seal (damaged)"],rewards:["900 Archaeology experience", "Access to the main fortress"],steps:["Speak to Dr Nabanik after completing the Archaeology tutorial and unlocking the Kharid-et Dig Site. Speak to him a second time to receive a centurion's seal (damaged). Dr Nabanik can be found next to the winch.", "Excavate the fort debris blocking the fort entrance until it dwindles down to nothing and the triangular entryway is revealed.", "After the entrance is completely revealed, a purple barrier will become visible. Restore the seal at an archaeologist's workbench with 6 Third Age iron and 2 Zarosian insignia.", "Go through the fort entrance with the restored centurion's seal in your backpack."]},
    "Prison Break": {tip:"Discover how to unlock the doors leading into the prison block under the fortress at the Kharid-et Dig Site.",loc:"Kharid-et Dig Site",req:"12 Archaeology (boostable), Breaking the Seal completed",items:["Custodian's log page 1", "Custodian's log page 2", "Custodian's log page 3", "Custodian's log page 4"],rewards:["900 Archaeology experience", "Access to the prison block"],steps:["Gather custodian's log page 1 and page 2 from legionary remains, castra debris or administratum debris found in the vicinity of the prison door in Kharid-et Dig Site. Any of these spots will drop any of the pages; there are four pages to collect to complete the mystery but only the first two are needed to access the prison.", "After collecting pages 1 and 2, talk to Liam; he will give you a broken Kharid-et prison dial, which needs to be put back into place to be able to open the door.", "Fix the broken dial (third one down) on the wall to the right of the prison door.", "To the left of the door, press the buttons in the following order: Shadow, Blood, Smoke, Ice.", "If not already collected, gather custodian's log page 3 and page 4 either from the same spots as above or from the newly unlocked praesidio remains and carcerem debris in the prison."],pages:[[0, "Custodian's log page 1"], [1, "Custodian's log page 2"], [2, "Custodian's log page 3"], [3, "Custodian's log page 4"]],auto:[[0, [0, 1]], [4, [2, 3]]]},
    "Time Served": {tip:"Unseal a door to reveal an inner vault hidden within Kharid-et's prison block.",loc:"Kharid-et Dig Site",req:"47 Archaeology, Prison Break completed",items:["Ancient timepiece (damaged)"],rewards:["2800 Archaeology experience", "Partial access to the Vault"],steps:["Excavate the praesidio remains in the prison block for an ancient timepiece (damaged).", "Restore the damaged artefact, producing an ancient timepiece, then return to the prison.", "Inspect the ancient mechanism; it becomes a cell controller. Insert the timepiece, choosing 'Yes, insert it.'"]},
    "The Forgotten Prisoner": {tip:"Help the strange device behind the maximum security barrier in Kharid-et's solitary confinement area remember its identity.",loc:"Kharid-et Dig Site",req:"107 Archaeology (boostable), Prison Break completed",items:["Pontifex signet ring (can be on the tool belt)", "Legatus pendant (can be on the tool belt)", "Portable phylactery"],rewards:["54000 Archaeology experience"],steps:["With the solitary confinement area in the prison block of Kharid-et Dig Site open, explore the area. The only area of interest is a maximum security barrier with a strange device behind it. To bypass this barrier you must have both a pontifex signet ring and legatus pendant, either equipped, on the toolbelt, or in the inventory. A pontifex signet ring is obtained from carcerem debris, which requires a legatus pendant in order to access.", "Interact with the strange device, which will request its identity. If one of these options is incorrect, you will need to start over from the first question.", "Tell it its name is Xil'gar Trog.", "Tell him he is a demon soul.", "Tell him that he is in a prison.", "Tell him he committed treason.", "Once all four questions are correctly answered, the strange device will realise who it was and introduce himself as Xil'gar Trog. Agree to help him further and enter a pseudo-contract in which you agree to free him. He will request you bring him a portable phylactery so he may be transferred into it.", "The portable phylactery can be obtained by excavating ancient magick munitions. Once repaired, bring it to him to receive Xil'gar Trog's soul."]},
    "The Cult of Orcus": {tip:"Find all three pater's log pages at Kharid-et and bring them to Dr Nabanik.",loc:"Kharid-et Dig Site",req:"74 Archaeology (boostable), Prison Break completed",items:["Pater's log page 1", "Pater's log page 2", "Pater's log page 3"],rewards:["11000 Archaeology experience"],steps:["Find all three pater's log pages from any of the following excavation hotspots: Kharid-et chapel debris (74 Archaeology), Pontifex remains (81 Archaeology), or Orcus altar (86 Archaeology).", "Talk to Dr Nabanik to complete the mystery. He is close to the bank in Kharid-et Dig Site."],pages:[[10, "Pater's log page 1"], [11, "Pater's log page 2"], [12, "Pater's log page 3"]],auto:[[0, [10, 11, 12]]]},
    "Shadow Fall": {tip:"Find all five praetorian's log pages at Kharid-et and talk to Dr Nabanik.",loc:"Kharid-et Dig Site",req:"107 Archaeology (boostable), Prison Break completed",items:["Praetorian's log page 1", "Praetorian's log page 2", "Praetorian's log page 3", "Praetorian's log page 4", "Praetorian's log page 5"],rewards:["54000 Archaeology experience"],steps:["Find all five praetorian's log pages from one of the excavation hotspots below: Ancient magick munitions (level 107 Archaeology), Praetorian remains (level 114 Archaeology), or War table debris (level 118 Archaeology).", "Talk to Dr Nabanik about the mystery."],pages:[[13, "Praetorian's log page 1"], [14, "Praetorian's log page 2"], [15, "Praetorian's log page 3"], [16, "Praetorian's log page 4"], [17, "Praetorian's log page 5"]],auto:[[0, [13, 14, 15, 16, 17]]]},
